def max_value_on_paths(N: int, grid_values: list[tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each path moves only right or down from the top-left (1,1) to the bottom-right (N,N).
    A cell's value can be collected at most once, even if both paths pass through it.
    """
    if N <= 0:
        return 0

    # Build the grid with 1-indexed coordinates from the input list
    grid = [[0] * N for _ in range(N)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x - 1][y - 1] = val

    # Use DP for two agents moving simultaneously
    size = N
    neg_inf = -10**15
    # dp_prev[i1][i2] - best sum when paths are at rows i1 and i2 after previous step
    dp_prev = [[neg_inf] * size for _ in range(size)]
    dp_prev[0][0] = grid[0][0]

    max_step = 2 * (N - 1)
    for step in range(1, max_step + 1):
        dp_cur = [[neg_inf] * size for _ in range(size)]
        # i1 row index for first path
        i1_min = max(0, step - (N - 1))
        i1_max = min(N - 1, step)
        for i1 in range(i1_min, i1_max + 1):
            j1 = step - i1
            if j1 < 0 or j1 >= N:
                continue
            # i2 for second path
            i2_min = max(0, step - (N - 1))
            i2_max = min(N - 1, step)
            for i2 in range(i2_min, i2_max + 1):
                j2 = step - i2
                if j2 < 0 or j2 >= N:
                    continue

                best = neg_inf
                # Consider all 4 previous moves (both up or left)
                for pi1 in (i1, i1 - 1):
                    if pi1 < 0 or pi1 > step - 1:
                        continue
                    pj1 = (step - 1) - pi1
                    if pj1 < 0 or pj1 >= N:
                        continue
                    for pi2 in (i2, i2 - 1):
                        if pi2 < 0 or pi2 > step - 1:
                            continue
                        pj2 = (step - 1) - pi2
                        if pj2 < 0 or pj2 >= N:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val > best:
                            best = prev_val

                if best == neg_inf:
                    continue

                cell_val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    cell_val += grid[i2][j2]
                dp_cur[i1][i2] = best + cell_val
        dp_prev = dp_cur

    result = dp_prev[N - 1][N - 1]
    return int(result if result != neg_inf else 0)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Convert a list of polynomial coefficients into a formatted string representation.
    """
    try:
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non‑negative integer")
        if not isinstance(coeffs, list):
            raise TypeError("coeffs must be a list")
        if len(coeffs) != n + 1:
            raise ValueError(f"coeffs length {len(coeffs)} does not match degree {n}")
        parts = []
        for idx, coeff in enumerate(coeffs):
            degree = n - idx
            if coeff == 0:
                continue
            # Determine sign
            sign = ''
            abs_coeff = coeff
            if coeff < 0:
                abs_coeff = -coeff
            if not parts:
                sign = '-' if coeff < 0 else ''
            else:
                sign = '-' if coeff < 0 else '+'
            # Determine coefficient part
            coeff_part = ''
            if degree == 0:
                coeff_part = str(abs_coeff)
            else:
                if abs_coeff != 1:
                    coeff_part = str(abs_coeff)
            # Determine variable part
            var_part = ''
            if degree == 0:
                var_part = ''
            elif degree == 1:
                var_part = 'x'
            else:
                var_part = f'x^{degree}'
            part = f"{sign}{coeff_part}{var_part}"
            parts.append(part)
        if not parts:
            return '0'
        return ''.join(parts)
    except Exception as e:
        # In case of unexpected errors, provide a clear message
        raise RuntimeError(f"Error generating polynomial string: {e}") from e

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.

    Examples:
    >>> decode("AA", "AB", "EOWIE")
    'Failed'    
    >>> decode("MSRTZCJKPFLQYVAWBINXUEDGHOOILSMIJFRCOPPQCEUNYDUMPP", "YIZSDWAHLNOVFUCERKJXQMGTBPPKOIYKANZWPLLVWMQJFGQYLL", "FLSO")
    'NOIP'
    """
    # Basic validation of lengths
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse = {}

    # Build bijective mapping from encoded to original
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"  # conflicting mapping
        else:
            if o in reverse and reverse[o] != e:
                return "Failed"  # another encoded letter already maps to this original
            mapping[e] = o
            reverse[o] = e

    # Ensure the mapping is complete for all 26 uppercase letters
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"  # unknown encoded letter
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def count_partitions(n: int, k: int, x: int) -> int:
    if not isinstance(n, int) or not isinstance(k, int) or not isinstance(x, int):
        raise TypeError("All arguments must be integers")
    if n < 0 or k <= 0 or x < 0:
        return 0
    # reduce the problem by subtracting the minimum required part from each of the k parts
    m = n - k * x
    if m < 0:
        return 0
    # dp[i][j] = number of partitions of integer i into parts of size at most j
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for j in range(k + 1):
        dp[0][j] = 1  # one way to partition zero
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]
    return dp[m][k]

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q)
    such that gcd(P, Q) == x0 and lcm(P, Q) == y0.
    """
    # Validate input
    if x0 <= 0 or y0 <= 0:
        return 0

    # y0 must be a multiple of x0
    if y0 % x0 != 0:
        return 0

    n = y0 // x0  # product of the reduced coprime factors

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(n**0.5) + 1
    for a in range(1, limit):
        if n % a != 0:
            continue
        b = n // a
        if _gcd(a, b) != 1:
            continue
        if a == b:
            count += 1
        else:
            count += 2
    return count

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalize for case-insensitive comparison
    scenario = scenario.upper()
    liar_names = {name.upper() for name in liar_count}
    day_names = {day.upper() for day in days_of_week}
    # Helper to determine if a statement concerns a day
    def contains_day(stmt: str) -> bool:
        tokens = stmt.upper().replace('.', '').split()
        return any(token in day_names for token in tokens)
    # Helper to parse a statement about guilt
    def parse_guilt(stmt: str):
        # Return (subject_name, claim_is_guilty) or None if not parsable
        stmt_u = stmt.upper()
        if 'NOT GUILTY' in stmt_u:
            claim = False
        elif 'GUILTY' in stmt_u:
            claim = True
        else:
            return None
        if stmt_u.startswith('I '):
            subject = None  # to be filled with speaker later
        else:
            subject = stmt.split()[0]  # keep original case for comparison
        return subject, claim
    for speaker, stmts in statements.items():
        speaker_up = speaker.upper()
        for st in stmts:
            if contains_day(st):
                continue
            parsed = parse_guilt(st)
            if parsed is None:
                continue  # ignore non-guilt statements
            subject, claim_guilty = parsed
            if subject is None:
                subject_name = speaker_up
            else:
                subject_name = subject.upper()
            # Determine truth value of the statement
            actual_guilty = subject_name == scenario
            truth = (actual_guilty == claim_guilty)
            is_liar = speaker_up in liar_names
            # Liars should utter false statements, truth-tellers true statements
            if is_liar:
                if truth:
                    return False
            else:
                if not truth:
                    return False
    return True

def count_apples_reachable(apple_heights: list[int], tao_reach: int) -> int:
    """
    Count how many apples Tao Tao can reach with or without a 30cm stool.

    A tomato is reachable if its height from the ground is less than or equal to
    the sum of Tao's natural reach and the stool height (30cm).
    Any invalid elements in the input list are ignored.
    """
    max_reach = tao_reach + 30  # 30cm stool can be used at most
    reachable = 0
    for h in apple_heights:
        try:
            if isinstance(h, (int, float)):
                if h <= max_reach:
                    reachable += 1
        except Exception:
            # ignore any element that causes an error
            continue
    return reachable

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    Args:
        T (int): The total time available for picking herbs.
        M (int): The number of different herbs in the cave.
        herbs (List[Tuple[int, int]]): A list of tuples, each containing the time required
                                      to pick the herb and its value.

    Returns:
        int: The maximum total value of herbs that can be picked within the time limit.
    """
    # Basic validation
    if not isinstance(T, int) or T < 0:
        raise ValueError("T must be a non‑negative integer")
    if not isinstance(M, int) or M < 0:
        raise ValueError("M must be a non‑negative integer")
    if not isinstance(herbs, list):
        raise TypeError("herbs must be a list of (int, int) tuples")
    if len(herbs) != M:
        # Adjust M if it doesn't match the list length
        M = len(herbs)

    # Initialize DP array
    dp = [0] * (T + 1)

    for idx, item in enumerate(herbs):
        try:
            time, value = item
        except Exception:
            raise TypeError(f"Herb at index {idx} is not a tuple of two integers")
        if not isinstance(time, int) or not isinstance(value, int):
            raise TypeError(f"Herb at index {idx} must contain integers")
        if time < 0 or value < 0:
            # Skip items with negative time or value
            continue
        if time > T:
            continue

        # 0/1 knapsack update
        for cap in range(T, time - 1, -1):
            new_val = dp[cap - time] + value
            if new_val > dp[cap]:
                dp[cap] = new_val

    return dp[T] if T >= 0 else 0

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    try:
        if not isinstance(heights, list):
            raise TypeError("heights must be a list")
        for h in heights:
            if not isinstance(h, int):
                raise TypeError("all elements in heights must be integers")
    except Exception as e:
        raise e

    n = len(heights)
    if n <= 1:
        return 0

    # inc[i] = length of Longest Increasing Subsequence ending at i
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # dec[i] = length of Longest Increasing Subsequence ending at i when traversed from right
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # calculate maximum bitonic length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
